{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "WITH c AS (SELECT trace_id, span_id, time, duration FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client'), s AS (SELECT trace_id, parent_span_id, time, duration FROM abnormal_traces WHERE service_name='geo' AND attr_span_kind='Server') SELECT count(*) n, approx_quantile(c.duration/1e6,0.5) client_ms, approx_quantile(s.duration/1e6,0.5) geo_server_ms, approx_quantile(epoch(s.time)-epoch(c.time),0.5)*1000 start_gap_ms FROM c JOIN s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id", "claim": "search's calls to geo take ~1400ms median client-side while geo server spans stay ~0.14ms; the gap is before geo starts."},
        {"kind": "trace", "sql": "SELECT 'ab' per, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY 2,3 UNION ALL SELECT 'no', span_name, attr_span_kind, count(*), round(approx_quantile(duration/1e6,0.95),1) FROM normal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') GROUP BY 2,3", "claim": "Only search's geo calls slowed (p95 ~2660ms vs 0.6ms); its rate calls from the same service stayed at ~8ms."},
        {"kind": "metric", "sql": "SELECT metric, attr_k8s_pod_name pod, round(avg(value),2) avgv FROM abnormal_metrics_sum WHERE attr_k8s_pod_name LIKE 'search%' AND metric IN ('k8s.pod.network.errors') GROUP BY 1,2", "claim": "search pods show zero network errors during the incident, so no transport-level loss is evident on its connections."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend",
     "evidence": [
       {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') OR (service_name='frontend' AND span_name='HTTP /hotels') GROUP BY 1,2,3", "claim": "search Nearby server p95 ~2667ms and frontend /hotels p95 ~2674ms in the incident, versus ~9-13ms normally, so the delay surfaces at the user-facing endpoint."}
     ]}
  ]
}
